// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type ClockAnimationProps = Record<string, any>;

const ClockAnimation: React.FC<ClockAnimationProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 60,
  clockBorderColor = "#222222",
  clockFaceColor = "#111111",
  tickColor = "#ffffff",
  secondHandColor = "#ff3366",
  minuteHandColor = "#ffffff",
  hourHandColor = "#aaaaaa",
  smoothSweep = false,
  showDigital = true,
  digitalTextColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Responsive sizing (optimizing for 9:16 vertical canvas or any other)
  const canvasMin = Math.min(width, height);
  const clockSize = canvasMin * 0.75;

  // Animation logic
  const clockScale = spring({
    fps,
    frame,
    config: { damping: 14, stiffness: 90 },
    durationInFrames: 30,
  });

  const clockOpacity = interpolate(frame, [0, 20], [0, 1]);

  // Time calculations
  const currentSeconds = frame / fps;
  
  // Rotations
  const secondHandRotation = smoothSweep 
    ? (currentSeconds / 60) * 360 
    : Math.floor(currentSeconds) * 6;
    
  // Minute hand completes 360 deg in 3600 seconds
  const minuteHandRotation = (currentSeconds / 3600) * 360;
  
  // Hour hand completes 360 deg in 43200 seconds (12 hours)
  const hourHandRotation = (currentSeconds / 43200) * 360;

  // Formatting digital clock (MM:SS)
  const displayMinutes = Math.floor(currentSeconds / 60).toString().padStart(2, "0");
  const displaySeconds = Math.floor(currentSeconds % 60).toString().padStart(2, "0");
  
  // Generate 60 ticks for the clock face
  const ticks = Array.from({ length: 60 }).map((_, i) => {
    const isMajor = i % 5 === 0;
    const tickWidth = isMajor ? clockSize * 0.012 : clockSize * 0.006;
    const tickHeight = isMajor ? clockSize * 0.04 : clockSize * 0.02;
    return (
      <div
        key={`tick-${i}`}
        style={{
          position: "absolute",
          top: clockSize * 0.02,
          left: `calc(50% - ${tickWidth / 2}px)`,
          width: tickWidth,
          height: tickHeight,
          backgroundColor: tickColor,
          transformOrigin: `50% ${clockSize / 2 - clockSize * 0.02}px`,
          transform: `rotate(${i * 6}deg)`,
          borderRadius: tickWidth / 2,
          opacity: isMajor ? 1 : 0.5,
          transition: "none",
        }}
      />
    );
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: robotoMonoFamily,
      }}
    >
      <div
        style={{
          width: clockSize,
          height: clockSize,
          borderRadius: "50%",
          backgroundColor: clockFaceColor,
          border: `${clockSize * 0.03}px solid ${clockBorderColor}`,
          position: "relative",
          transform: `scale(${clockScale})`,
          opacity: clockOpacity,
          boxShadow: "0 25px 50px -12px rgba(0,0,0,0.5)",
          transition: "none",
        }}
      >
        {/* Ticks */}
        {ticks}

        {/* Digital Time Display */}
        {showDigital && (
          <div
            style={{
              position: "absolute",
              top: "65%",
              width: "100%",
              textAlign: "center",
              fontSize: clockSize * 0.1,
              fontWeight: 600,
              color: digitalTextColor,
              letterSpacing: "0.05em",
              transition: "none",
            }}
          >
            {displayMinutes}:{displaySeconds}
          </div>
        )}

        {/* Hour Hand */}
        <div
          style={{
            position: "absolute",
            bottom: "50%",
            left: `calc(50% - ${clockSize * 0.015}px)`,
            width: clockSize * 0.03,
            height: clockSize * 0.25,
            backgroundColor: hourHandColor,
            transformOrigin: "bottom center",
            transform: `rotate(${hourHandRotation}deg)`,
            borderRadius: clockSize * 0.015,
            zIndex: 1,
            transition: "none",
          }}
        />

        {/* Minute Hand */}
        <div
          style={{
            position: "absolute",
            bottom: "50%",
            left: `calc(50% - ${clockSize * 0.01}px)`,
            width: clockSize * 0.02,
            height: clockSize * 0.35,
            backgroundColor: minuteHandColor,
            transformOrigin: "bottom center",
            transform: `rotate(${minuteHandRotation}deg)`,
            borderRadius: clockSize * 0.01,
            zIndex: 2,
            transition: "none",
          }}
        />

        {/* Second Hand */}
        <div
          style={{
            position: "absolute",
            bottom: "50%",
            left: `calc(50% - ${clockSize * 0.006}px)`,
            width: clockSize * 0.012,
            height: clockSize * 0.42,
            backgroundColor: secondHandColor,
            transformOrigin: "bottom center",
            transform: `rotate(${secondHandRotation}deg)`,
            borderRadius: clockSize * 0.006,
            zIndex: 3,
            transition: "none",
          }}
        />
        
        {/* Second Hand Counter-balance (Tail) */}
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: `calc(50% - ${clockSize * 0.006}px)`,
            width: clockSize * 0.012,
            height: clockSize * 0.08,
            backgroundColor: secondHandColor,
            transformOrigin: "top center",
            transform: `rotate(${secondHandRotation}deg)`,
            borderRadius: clockSize * 0.006,
            zIndex: 3,
            transition: "none",
          }}
        />

        {/* Center Pivot Dot */}
        <div
          style={{
            position: "absolute",
            top: `calc(50% - ${clockSize * 0.03}px)`,
            left: `calc(50% - ${clockSize * 0.03}px)`,
            width: clockSize * 0.06,
            height: clockSize * 0.06,
            borderRadius: "50%",
            backgroundColor: secondHandColor,
            border: `${clockSize * 0.01}px solid ${clockFaceColor}`,
            zIndex: 4,
            transition: "none",
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default ClockAnimation;